PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE employee_accounts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    staff_code TEXT UNIQUE NOT NULL,
    display_name TEXT NOT NULL,
    department TEXT DEFAULT '',
    role TEXT DEFAULT 'employee',
    pin_salt TEXT NOT NULL,
    pin_hash TEXT NOT NULL,
    enabled INTEGER DEFAULT 1,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE employee_profiles (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    staff_code TEXT NOT NULL,
    display_name TEXT NOT NULL,
    department TEXT DEFAULT '',
    role TEXT DEFAULT 'employee',
    position_title TEXT DEFAULT '',
    gender TEXT DEFAULT '',
    phone TEXT DEFAULT '',
    email TEXT DEFAULT '',
    employment_status TEXT DEFAULT '',
    hire_date TEXT DEFAULT '',
    permission_scope TEXT DEFAULT '',
    app_access TEXT DEFAULT '',
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
    job_grade TEXT DEFAULT ''
, area TEXT DEFAULT '', is_area_lead INTEGER DEFAULT 0, base_salary INTEGER DEFAULT 0, allowance INTEGER DEFAULT 0, bonus INTEGER DEFAULT 0, salary_grade TEXT DEFAULT '', years_of_service REAL DEFAULT 0, annual_leave_days INTEGER DEFAULT 0, used_leave_days REAL DEFAULT 0, remaining_leave_days REAL DEFAULT 0);
CREATE TABLE employee_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    session_token TEXT UNIQUE NOT NULL,
    staff_code TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE employee_proxy_settings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    staff_code TEXT NOT NULL,
    proxy_one TEXT DEFAULT '',
    proxy_two TEXT DEFAULT '',
    proxy_one_status TEXT DEFAULT '',
    proxy_two_status TEXT DEFAULT '',
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
, display_name TEXT DEFAULT '', department TEXT DEFAULT '', proxy_one_staff_code TEXT DEFAULT '', proxy_one_name TEXT DEFAULT '', proxy_one_requested_at TEXT DEFAULT '', proxy_one_accepted_at TEXT DEFAULT '', proxy_two_staff_code TEXT DEFAULT '', proxy_two_name TEXT DEFAULT '', proxy_two_requested_at TEXT DEFAULT '', proxy_two_accepted_at TEXT DEFAULT '');
CREATE TABLE buildings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    building_no TEXT NOT NULL,
