    display_address TEXT DEFAULT '',
    management_company TEXT DEFAULT '',
    management_phone TEXT DEFAULT '',
    manager_name TEXT DEFAULT '',
    manager_phone TEXT DEFAULT '',
    active_users INTEGER DEFAULT 0,
    total_households INTEGER DEFAULT 0,
    ip TEXT DEFAULT '',
    host TEXT DEFAULT '',
    note TEXT DEFAULT '',
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
, contract_status TEXT DEFAULT '', monthly_revenue INTEGER DEFAULT 0, building_type TEXT DEFAULT '', service_level TEXT DEFAULT '', public_facility_status TEXT DEFAULT '', manager_age TEXT DEFAULT '', manager_experience TEXT DEFAULT '', manager_interest TEXT DEFAULT '', visit_time TEXT DEFAULT '', committee_time TEXT DEFAULT '', resident_meeting_time TEXT DEFAULT '');
CREATE TABLE customer_accounts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    customer_no TEXT DEFAULT '',
    customer_name TEXT DEFAULT '',
    building_no TEXT DEFAULT '',
    area TEXT DEFAULT '',
    address TEXT DEFAULT '',
    phone TEXT DEFAULT '',
    service_status TEXT DEFAULT '',
    payment_status TEXT DEFAULT '',
    monthly_fee INTEGER DEFAULT 0,
    is_overdue INTEGER DEFAULT 0,
    ip_limited INTEGER DEFAULT 0,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
, install_date TEXT DEFAULT '', last_payment_date TEXT DEFAULT '', arrears_months INTEGER DEFAULT 0, plan_name TEXT DEFAULT '', router_model TEXT DEFAULT '', customer_type TEXT DEFAULT '', customer_phone TEXT DEFAULT '', floor_text TEXT DEFAULT '', room_no TEXT DEFAULT '', service_address TEXT DEFAULT '', service_type TEXT DEFAULT '', package_name TEXT DEFAULT '', contract_status TEXT DEFAULT '', account_status TEXT DEFAULT '', payment_method TEXT DEFAULT '', billing_day INTEGER DEFAULT 0, arrears_status TEXT DEFAULT '', equipment_no TEXT DEFAULT '', cm_mac TEXT DEFAULT '', ip_address TEXT DEFAULT '', signal_note TEXT DEFAULT '', billing_note TEXT DEFAULT '', service_note TEXT DEFAULT '');
CREATE TABLE tickets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ticket_no TEXT NOT NULL,
    dispatch_area TEXT DEFAULT '',
    case_type TEXT NOT NULL,
    status TEXT NOT NULL,
    customer_name TEXT NOT NULL,
    contact_name TEXT NOT NULL,
    contact_phone TEXT NOT NULL,
    service_address TEXT NOT NULL,
    appointment_date TEXT DEFAULT '',
    appointment_time TEXT DEFAULT '',
    assigned_engineer TEXT DEFAULT '',
    assigned_engineer_staff_code TEXT DEFAULT '',
    customer_no TEXT DEFAULT '',
    building_no TEXT DEFAULT '',
    description TEXT DEFAULT '',
    internal_note TEXT DEFAULT '',
    completion_note TEXT DEFAULT '',
