    extra_fees_data TEXT DEFAULT '',
    customer_signature_data TEXT DEFAULT '',
    customer_signature_signed_at TEXT DEFAULT '',
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    arrived_at TEXT DEFAULT '',
    completed_at TEXT DEFAULT ''
, repair_category TEXT DEFAULT '', repair_reason TEXT DEFAULT '', is_public_facility INTEGER DEFAULT 0, is_non_general_repair INTEGER DEFAULT 0, material_usage_json TEXT DEFAULT '', speedtest_photo_data TEXT DEFAULT '', before_photos_data TEXT DEFAULT '', after_photos_data TEXT DEFAULT '', finished_by_staff_code TEXT DEFAULT '', finished_by_name TEXT DEFAULT '', finished_at TEXT DEFAULT '', source_channel TEXT DEFAULT '', call_attempts INTEGER DEFAULT 0, voice_message_left INTEGER DEFAULT 0, same_day_confirmed INTEGER DEFAULT 0, customer_valid_checked INTEGER DEFAULT 0, billing_checked INTEGER DEFAULT 0, oral_troubleshooting_done INTEGER DEFAULT 0, boss_review_required INTEGER DEFAULT 0);
