, plan_label TEXT DEFAULT '', billing_category TEXT DEFAULT '', updated_at TEXT DEFAULT '');
CREATE TABLE customer_service_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    customer_no TEXT DEFAULT '',
    item_type TEXT DEFAULT '',
