, plan_code TEXT DEFAULT '', enabled INTEGER DEFAULT 1, updated_at TEXT DEFAULT '');
CREATE TABLE purchase_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    request_no TEXT DEFAULT '',
