    id INTEGER PRIMARY KEY AUTOINCREMENT,
    holiday_date TEXT DEFAULT '',
    title TEXT DEFAULT '',
    enabled INTEGER DEFAULT 1,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
, holiday_type TEXT DEFAULT '', is_rest_day INTEGER DEFAULT 1, is_makeup_workday INTEGER DEFAULT 0, source TEXT DEFAULT 'manual', source_year INTEGER DEFAULT 0, note TEXT DEFAULT '');
CREATE TABLE employee_holidays (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    holiday_date TEXT DEFAULT '',
    holiday_name TEXT DEFAULT '',
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE ticket_install_details (
	id INTEGER NOT NULL,
	ticket_id INTEGER NOT NULL,
	deposit_amount NUMERIC(12, 2) NOT NULL,
	construction_fee NUMERIC(12, 2) NOT NULL,
	monthly_fee NUMERIC(12, 2) NOT NULL,
	monthly_fee_1 NUMERIC(12, 2) NOT NULL,
	monthly_fee_2 NUMERIC(12, 2) NOT NULL,
	monthly_fee_3 NUMERIC(12, 2) NOT NULL,
	month_count INTEGER NOT NULL,
	other_fee NUMERIC(12, 2) NOT NULL,
	other_fee_1 NUMERIC(12, 2) NOT NULL,
	other_fee_2 NUMERIC(12, 2) NOT NULL,
	other_fee_note TEXT,
	material_name VARCHAR(100),
	material_quantity INTEGER NOT NULL,
	usage_start_date VARCHAR(20),
	usage_end_date VARCHAR(20),
	usage_month_count INTEGER NOT NULL,
	rent_subtotal NUMERIC(12, 2) NOT NULL,
	total_amount NUMERIC(12, 2) NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (ticket_id),
	FOREIGN KEY(ticket_id) REFERENCES tickets (id)
);
CREATE TABLE ticket_return_details (
	id INTEGER NOT NULL,
	ticket_id INTEGER NOT NULL,
	payment_record TEXT,
	deposit_amount NUMERIC(12, 2) NOT NULL,
	refund_amount NUMERIC(12, 2) NOT NULL,
	deduction_amount NUMERIC(12, 2) NOT NULL,
	device_fee NUMERIC(12, 2) NOT NULL,
	cleaning_fee NUMERIC(12, 2) NOT NULL,
	other_fee NUMERIC(12, 2) NOT NULL,
	other_fee_note TEXT,
	total_amount NUMERIC(12, 2) NOT NULL,
	returned_device_status VARCHAR(100),
	return_note TEXT,
	settlement_note TEXT,
	PRIMARY KEY (id),
	UNIQUE (ticket_id),
	FOREIGN KEY(ticket_id) REFERENCES tickets (id)
);
CREATE TABLE employee_rest_months (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                staff_code TEXT NOT NULL,
                year INTEGER NOT NULL,
                month INTEGER NOT NULL,
                rest_dates TEXT DEFAULT '[]',
                note TEXT DEFAULT '',
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(staff_code, year, month)
            );
