CREATE TABLE _codex_write_probe(id integer primary key, created_at text default current_timestamp);
CREATE TABLE hr_salary_profiles (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                staff_code TEXT UNIQUE NOT NULL,
