            );
CREATE TABLE hr_leave_requests (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                leave_no TEXT UNIQUE DEFAULT '',
                staff_code TEXT DEFAULT '',
                display_name TEXT DEFAULT '',
                department TEXT DEFAULT '',
                leave_date TEXT DEFAULT '',
                leave_type TEXT DEFAULT '',
                reason TEXT DEFAULT '',
                status TEXT DEFAULT '待審核',
                review_note TEXT DEFAULT '',
                reviewed_by TEXT DEFAULT '',
                reviewed_at TEXT DEFAULT '',
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE INDEX ix_ticket_install_details_id ON ticket_install_details (id);
CREATE INDEX ix_ticket_return_details_id ON ticket_return_details (id);
PRAGMA writable_schema=OFF;
COMMIT;
